// #region Typings
export interface TextAreaControlledProps {
  /** The default value of the textarea. */
  defaultValue?: never;
  /** The current value of the textarea. */
  value: string;
  /** Handler that is called when the value changes. */
  onChange: (value: string, event: ChangeEvent<HTMLTextAreaElement>) => void;
}

export interface TextAreaUncontrolledProps {
  /** The default value of the textarea. */
  defaultValue?: string;
  /** The current value of the textarea. */
  value?: never;
  /** Handler that is called when the value changes. */
  onChange?: never;
}

export interface TextAreaBaseProps
  extends DOMProps,
    AriaLabelingProps,
    FocusEvents,
    KeyboardEvents,
    FormControlStateProps,
    StylingProps,
    DataTestId {
  /**
   * Whether the textarea is disabled.
   * If true, the user cannot interact with the control.
   * @defaultValue false
   */
  disabled?: boolean;
  /**
   * Whether the textarea is required for form submission.
   * If true, the user must fill in a value before submitting a form, otherwise the error styling is applied.
   * @defaultValue false
   */
  required?: boolean;
  /**
   * Whether the textarea is readonly.
   * If true, the user cannot modify the value of the control. Unlike the disabled attribute,
   * the readonly attribute does not prevent the user from clicking or selecting in the control.
   * The value of a read-only control is still submitted with the form.
   * @defaultValue false
   */
  readOnly?: boolean;
  /**
   * A hint to the user of what can be entered in the control.
   * If set, it is shown when there is no text inside the textarea.
   */
  placeholder?: string;
  /**
   * This attribute indicates whether the textarea is resizable by the user, and, if so, in which direction.
   * @defaultValue 'both'
   */
  resize?: 'both' | 'vertical' | 'horizontal' | 'none';
  /**
   * The visible width of the text control, in average character widths.
   * If it is specified, it must be a positive integer.
   * @defaultValue 20
   */
  cols?: number;
  /**
   * The number of visible text lines for the control. If it is specified, it must be a positive integer.
   * @defaultValue 2
   */
  rows?: number;
  /**
   * The minimum number of characters required that the user should enter.
   * Doesn't stop the user from removing characters so that the number entered goes past the minimum,
   * but it does make the value entered into the <textarea> invalid.
   * With a set minlength an empty <textarea> is still considered valid unless you also have the required attribute set.
   */
  minLength?: number;
  /**
   * The maximum number of characters that the user can enter. If this value isn't specified,
   * the user can enter an unlimited number of characters.
   */
  maxLength?: number;
  /**
   * This attribute indicates whether the value of the control can be automatically completed by the browser.
   * If no autocompletion is desired, it can be set to "off".
   */
  autoComplete?: string;
  /** The name of the control - used when submitting the textarea in a form. */
  name?: string;
  /**
   * The width of the text area. It can be set to any fixed width, can take the width of its content, or can take the full width of its container when set to 'full'.
   * @defaultValue 'content'
   */
  width?: TextAreaWidth;
  /**
   * Test id used for matching the textarea container.
   * @defaultValue 'text-area-root'
   */
  'data-testid'?: string;
}

export type TextAreaProps = TextAreaBaseProps &
  (TextAreaUncontrolledProps | TextAreaControlledProps);

export type TextAreaWidth =
  | 'content'
  | 'full'
  | Property.Width<string & Record<string, never>>;
// #endregion

/**
 * The `TextArea` component can be used as a multi-line plain-text editing control to
 * enter free-form text, such as a comment on a form.
 */
export const TextArea = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  TextAreaProps
>((props, forwardedRef) => {
  const {
    onChange,
    minLength,
    maxLength,
    id: propId,
    disabled: propDisabled,
    required: propRequired,
    readOnly = false,
    resize = 'both',
    controlState,
    value: propValue,
    defaultValue,
    width = 'content',
    'aria-describedby': ariaDescribedby,
    'data-testid': dataTestId,
    className: consumerClassName,
    style: consumerStyle,
    ...remainingProps
  }: TextAreaProps = props;

  const {
    controlId,
    required: contextRequired,
    disabled: contextDisabled,
    dispatch,
  } = _useFormFieldContext();

  if (
    (propId !== undefined && propId !== controlId) ||
    (propDisabled !== undefined && propDisabled !== contextDisabled) ||
    (propRequired !== undefined && propRequired !== contextRequired)
  ) {
    dispatch?.({
      type: FormFieldAction.UPDATE,
      payload: {
        id: propId,
        disabled: propDisabled,
        required: propRequired,
      },
    });
  }

  const id = propId || controlId;
  const disabled = propDisabled || contextDisabled;
  const required = propRequired || contextRequired;

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [hasFocus, setFocus] = useState<boolean>();
  const [hasError, hint] = _useFormControlState(controlState);

  const [value, setValue] = _useControllableState({
    defaultValue,
    value: propValue,
  });

  const handleChange = (event: ChangeEvent<HTMLTextAreaElement>) => {
    const newValue = event.target?.value;
    setValue(newValue);
    onChange?.(newValue, event);
  };

  const [isTouchedAndInvalid, setIsTouchedAndInvalid] = useState(false);
  const { containerProps, inputProps, hintProps } = _useInputHint({
    ariaDescribedby,
    hint,
    hasError: hasError || isTouchedAndInvalid,
  });

  useEffect(() => {
    // The ValidityState interface is used to correctly style the Hint, since the structure of the DOM does not allow using the CSS :invalid pseudo-class.
    setIsTouchedAndInvalid(
      !textareaRef.current?.validity.valid && hasFocus !== undefined,
    );
    /**
     * Watching the props controlled by the TextArea knobs to represent the currently configured (error) state.
     * Example: If required was set to true after touching the textarea, the hint was not marked as error, because the hasError prop wasn't updated.
     */
  }, [hasFocus, controlState, required]);

  const { focusProps, focusClassName } = useFocusRing({
    variant: hasError || isTouchedAndInvalid ? 'critical' : 'neutral',
    ignoreModality: true,
  });

  return (
    <Flex
      gap={4}
      flexDirection="column"
      data-testid={dataTestId}
      ref={forwardedRef}
      className={consumerClassName}
      style={consumerStyle}
      {...containerProps}
    >
      <Flex gap={0}>
        <textarea
          ref={textareaRef}
          data-testid="text-area"
          id={id}
          minLength={minLength}
          maxLength={maxLength}
          className={clsx(
            {
              'strato-form-error': hasError,
              'strato-form-touched': hasFocus !== undefined,
              'strato-form-resizable': resize !== 'none',
            },
            textAreaCSS({
              resize,
            }),
            textAreaWidths[width],
            focusClassName,
          )}
          style={{
            width: width !== 'content' && width !== 'full' ? width : undefined,
          }}
          disabled={disabled}
          required={required}
          readOnly={readOnly}
          value={value}
          aria-required={required}
          onChange={handleChange}
          {..._mergeProps(
            remainingProps,
            focusProps,
            {
              onFocus: () => setFocus(true),
              onBlur: () => setFocus(false),
            },
            inputProps,
          )}
        />
        {resize !== 'none' && (
          <div className={textAreaContainerCSS}>
            <span
              className={textAreaResizerCSS({
                hasError,
                disabled,
                touched: isTouchedAndInvalid,
              })}
            />
          </div>
        )}
      </Flex>
      <Hint
        hasError={hasError || isTouchedAndInvalid}
        disabled={disabled}
        {...hintProps}
      >
        {hint}
      </Hint>
    </Flex>
  );
});
(TextArea as typeof TextArea & { displayName: string }).displayName =
  'TextArea';
